/** 按「具体问题 × 牌」存储的解读内容（键 → 内容） */
const STORE: Record<string, MasterQuestionCardContent> = {};

function register(
  categoryId: string,
  questionText: string,
  cardId: string,
  upright: boolean,
  content: MasterQuestionCardContent
): void {
  const key = masterQuestionContentKey(categoryId, questionText, cardId, upright);
  STORE[key] = content;
}

/** 占位文案：无正式解读时返回，便于 78×2×题目 全覆盖展示并标注「撰写中」 */
function generatePlaceholder(
  cardId: string,
  upright: boolean,
  questionText: string,
  cardName: string
): MasterQuestionCardContent {
  const orientation = upright ? '正位' : '逆位';
  const hint = `此牌（${cardName}${orientation}）针对「${questionText}」的专属解读正在精心撰写中，敬请期待。您可先参考本牌在该大类的通用解读。`;
  return {
    cardSpeaking: `【牌在对你说话】${hint}`,
    psychologyLayer: `【心理层面】${hint}`,
    spiritLayer: `【灵性层面】${hint}`,
    actionPath: `【行动路径】${hint}`,
    masterSummary: `【大师总结】${hint}`,
    isPlaceholder: true,
  };
}

/** 获取「具体问题 × 牌」大师解读（四大类专用）。
 * 若传入 options.placeholder === true 且无已入库内容，则返回占位解读（isPlaceholder: true），保证 78×2×题目 均有五段式展示。 */
export function getMasterQuestionContent(
  categoryId: string,
  questionText: string,
  cardId: string,
  upright: boolean,
  options?: { placeholder?: boolean }
): MasterQuestionCardContent | null {
  const q = questionText?.trim() ?? '';
  const key = masterQuestionContentKey(categoryId, q, cardId, upright);
  let stored = STORE[key];
  if (!stored && QUESTION_ALIASES[q]) {
    const canonical = QUESTION_ALIASES[q];
    stored = STORE[masterQuestionContentKey(categoryId, canonical, cardId, upright)];
  }
  if (stored) return stored;
  if (options?.placeholder) {
    const cardName = getTarotCardById(cardId)?.nameZh ?? cardId;
    return generatePlaceholder(cardId, upright, (q || questionText?.trim()) ?? '', cardName);
  }
  return null;
}

/** 某大类下「具体问题 × 78 张牌 × 正逆位」全部组合，用于批量生成或统计待撰写条数 */
export function getAllMasterQuestionContentKeys(categoryId: string): {
  questionText: string;
  cardId: string;
  upright: boolean;
}[] {
  const questions = getQuestionsForCategory(categoryId);
  const cards = getAllTarotCards();
  const out: { questionText: string; cardId: string; upright: boolean }[] = [];
  for (const questionText of questions) {
    for (const card of cards) {
      out.push({ questionText, cardId: card.id, upright: true });
      out.push({ questionText, cardId: card.id, upright: false });
    }
  }
  return out;
}

